-- Enable RCSI (SQL Server; already ON in Azure SQL Database)
ALTER DATABASE Sales SET READ_COMMITTED_SNAPSHOT ON WITH ROLLBACK IMMEDIATE;

-- Allow and use SNAPSHOT isolation
ALTER DATABASE Sales SET ALLOW_SNAPSHOT_ISOLATION ON;
SET TRANSACTION ISOLATION LEVEL SNAPSHOT;
BEGIN TRAN;
    SELECT SUM(Total) FROM dbo.Orders;   -- consistent as of transaction start
    SELECT COUNT(*)   FROM dbo.Orders;   -- same snapshot
COMMIT;

ALTER TABLE dbo.Products ADD RowVer ROWVERSION;

UPDATE dbo.Products
SET Price = @newPrice
WHERE ProductId = @id AND RowVer = @originalRowVer;

IF @@ROWCOUNT = 0
    THROW 50409, 'The product was modified by another user.', 1;

ALTER DATABASE CURRENT SET COMPATIBILITY_LEVEL = 170;
ALTER DATABASE SCOPED CONFIGURATION SET MAXDOP = 8;
ALTER DATABASE SCOPED CONFIGURATION SET OPTIMIZE_FOR_AD_HOC_WORKLOADS = ON;
ALTER DATABASE CURRENT SET QUERY_STORE = ON (OPERATION_MODE = READ_WRITE, QUERY_CAPTURE_MODE = AUTO);
ALTER DATABASE CURRENT SET ACCELERATED_DATABASE_RECOVERY = ON;   -- SQL Server
